assert a in s
b = """PREV = S + '/report/prev'
A0 = ['<style>.pg2 { display: grid; grid-template-columns: 1fr 1fr; gap: 8pt; align-items: start; } .pg2 img { width: 100%; height: auto; max-height: 228mm; object-fit: contain; } .pg2.tall img { width: auto; max-width: 100%; margin: 0 auto; } figure.page .wide { width: 100%; height: auto; max-height: none; } .pg2 img.fr { max-height: none; }</style>',
      '  <h3 style="margin-top:14pt">A0 · Saturday 10 October: the earlier products (advisories 12, 14 and 15)</h3><p class="small">Reproduced as issued, from the author\\'s files; nothing has been edited or re-rendered. They predate the building sets and are assessed in section 4.1. The figure labels on the Saturday pages are those of the products themselves.</p>',
      f'  <figure class="page"><div class="pg2 tall"><img src="file://{PREV}/adv12_hourly_sun4pm.png" alt="Hour-by-hour map, Sunday 4 pm"><img src="file://{PREV}/adv12_hourly_sun10pm.png" alt="Hour-by-hour map, Sunday 10 pm"></div><figcaption><b>A0-maps.</b> Hour-by-hour maps on advisory 12 (Saturday 3 am), two frames of a sequence: Sunday 4 pm (left) with 90 mph sustained and 115 mph gusts at the Amapas house, the center "5 nm south" and both addresses "extreme"; Sunday 10 pm (right) with 40 mph and the center 89 km north. Wind interpolated from the NHC forecast points; zones by judgment, as the footer says.</figcaption></figure>',
      f'  <figure class="page"><img src="file://{PREV}/adv14_model_snapshot.png" alt="Model snapshot, Saturday 5:36 pm"><figcaption><b>A0-snapshot.</b> Model snapshot, Saturday 5:36 pm (advisory 14): the NHC median wind bracket, a seventh-floor scenario, a five-model rain blend, offshore wave guidance, three flood mechanisms with two marked unresolved, and the historical comparison.</figcaption></figure>',
      f'  <figure class="page"><img class="wide" src="file://{PREV}/video15_panels.png" alt="Panels from the Saturday-night videos"><figcaption><b>A0-video.</b> Twelve panels from the two Saturday-night videos (advisory 15, data stamp Saturday 8:30 pm): category, rain history, terrain, wind by height, the Amapas slope, the NHC forecast with its 75/37/15% odds and a pass about 15 km west around midnight, the Sunday–Monday timeline, how the forecast had changed, when it would be known, and how far off the center could pass.</figcaption></figure>',
      '  <figure class="page"><div class="pg2">' + ''.join(f'<img class="fr" src="file://{PREV}/frames/risk15_t{t}.png" alt="Risk video frame at {t} s">' for t in (290, 368, 386, 404, 458, 470)) + '</div><figcaption><b>A0-video frames.</b> Six frames from the risk video (8 min 34 s, 720p export): wind by height and terrain; the hour-by-hour bars for Amapas, Emiliano Zapata and El Pitillal; the NHC forecast panel with the satellite image; and the Sunday–Monday timeline.</figcaption></figure>',
      f'  <figure class="page"><div class="pg2 tall"><img src="file://{PREV}/adv15_pitillal_table.png" alt="El Pitillal hour-by-hour table"><img src="file://{PREV}/adv15_pitillal_card.png" alt="El Pitillal start, worst, end card"></div><figcaption><b>A0-table.</b> El Pitillal hour by hour (advisory 15, Saturday 9 pm) and its three-line card: five classes from "poco" to "no salir" for wind, rain and river; starts Sunday 2 pm, worst 10 pm Sunday to 4 am Monday, over by 9 am Monday.</figcaption></figure>']
""" + a.replace("rendered in English on a white background for print. Each set", "the Saturday products reproduced as issued and the Sunday and Monday sets rendered in English on a white background for print. Each set") + "\nappA += A0"
s = s.replace(a, b)
reps = [
 ("Figure 5 uses the building summaries\\' own numbers (bay.json for each version) and the airport reports (METAR MMPR) from Sunday 3 pm to Monday 8 am.", "Figure 5a uses the building summaries\\' own numbers (bay.json for each version) and the airport reports (METAR MMPR) from Sunday 3 pm to Monday 8 am. Appendix A0 reproduces the Saturday products as issued (the author\\'s files): the advisory-12 maps, the advisory-14 snapshot and the advisory-15 table and card as supplied, and six frames from the 720p export of the risk video; Figure 5b reads their headline numbers from the images."),
]
for a, b in reps:
    assert a in s, a[:70]; s = s.replace(a, b)
open(p, 'w', encoding='utf-8').write(s); print('assemble patched')
